INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(1300, 'fair', '/fer/', 'adjective / noun', '{"zh-TW":["公平的；展覽會"],"en":["treating people equally; a commercial exhibition"]}', NULL, 'fair price/trade fair', '[{"en":"We offer fair prices to all customers.","zh-TW":"我們對所有客戶提供公平的價格。"},{"en":"We met potential clients at the trade fair.","zh-TW":"我們在商展上認識了潛在客戶。"}]', '{"noun":"fairness","adjective":"fair","adverb":"fairly"}', NULL, 1, 1300, NULL),
(1301, 'fall', '/fɔːl/', 'verb', '{"zh-TW":["【主要意義-動詞/名詞】落下；跌倒","【次要意義-名詞（美式）】秋天","【次要意義-名詞】瀑布（複數 falls）","【次要意義-動詞】淪為；變成某種狀態"],"en":["[primary] to drop or descend; the act of dropping","[secondary - noun (AmE)] autumn","[secondary - noun] a waterfall (often plural)","[secondary - verb] to enter or pass into a state"]}', NULL, 'fall due / fall short / fall into place / fall flat / Niagara Falls', '[{"en":"Sales figures fell short of the projected targets for the quarter.","zh-TW":"本季的銷售數字未達預期目標。"},{"en":"The payment falls due on the last business day of each month.","zh-TW":"款項在每月最後一個工作日到期。"},{"en":"The new marketing plan fell flat with focus groups.","zh-TW":"新的行銷計劃在焦點小組中未能引起反響。"}]', '{"noun":"downfall","adjective":"fallen"}', 'fall 有多個次要意義：fall short（未達到）、fall due（到期）、fall flat（失敗/未引起反響）均為 TOEIC 閱讀高頻商業用語，不可望文生義。', 1, 1301, NULL),
(1302, 'familiar', '/fəˈmɪliər/', 'adjective', '{"zh-TW":["熟悉的"],"en":["well known; often seen or experienced"]}', NULL, 'familiar with', '[{"en":"Are you familiar with this software?","zh-TW":"你熟悉這個軟體嗎？"},{"en":"The process should be familiar to all staff.","zh-TW":"所有員工應該熟悉這個流程。"}]', '{"noun":"familiarity","verb":"familiarize","adjective":"familiar"}', NULL, 3, 1302, NULL),
(1303, 'family', '/ˈfæməli/', 'noun', '{"zh-TW":["家庭；家族"],"en":["a group of related people","a group of related things"]}', NULL, 'family business / family-friendly', '[{"en":"It is a family-owned business.","zh-TW":"這是一家家族企業。"},{"en":"The company offers family-friendly policies.","zh-TW":"公司提供家庭友善政策。"}]', '{"noun":"family","adjective":"familiar","noun2":"familiarity"}', NULL, 2, 1303, NULL),
(1304, 'famous', 'ˈfeɪməs', 'adjective', '{"zh-TW":["著名的；有名的","出名的"],"en":["known by many people","well-known"]}', NULL, 'famous brand/world-famous', '[{"en":"The company is famous for its innovation.","zh-TW":"該公司以其創新而聞名。"}]', '{"noun":"fame","adverb":"famously"}', NULL, 2, 1304, NULL),
(1305, 'fan', '/fæn/', 'noun', '{"zh-TW":["粉絲；風扇"],"en":["a person who admires someone or something"]}', NULL, 'fan base / big fan', '[{"en":"I''m a big fan of this band.","zh-TW":"我是這個樂隊的忠實粉絲。"},{"en":"Turn on the fan, it''s hot.","zh-TW":"開風扇，好熱。"}]', NULL, NULL, 1, 1305, NULL),
(1306, 'far', '/fɑːr/', 'adverb', '{"zh-TW":["遠；遠遠地"],"en":["at a great distance","to a great degree"]}', NULL, 'so far / by far', '[{"en":"So far, everything is going well.","zh-TW":"到目前為止，一切順利。"},{"en":"This is by far the best option.","zh-TW":"這無疑是最好的選擇。"}]', '{"adverb":"far","adjective":"far","adjective2":"farther"}', NULL, 1, 1306, NULL),
(1307, 'fare', '/fer/', 'noun', '{"zh-TW":["票價；費用"],"en":["the money paid for a journey"]}', NULL, 'bus/air fare', '[{"en":"Air fares have increased significantly.","zh-TW":"機票價格大幅上漲。"},{"en":"What is the fare to the airport?","zh-TW":"到機場的票價是多少？"}]', '{"noun":"fare"}', NULL, 1, 1307, NULL),
(1308, 'fashion', '/ˈfæʃən/', 'noun', '{"zh-TW":["時尚；方式"],"en":["a popular trend; a manner of doing something"]}', NULL, 'in a timely fashion', '[{"en":"The fashion industry is worth billions.","zh-TW":"時尚產業價值數十億。"},{"en":"The work was completed in a professional fashion.","zh-TW":"工作以專業方式完成。"}]', '{"noun":"fashion","adjective":"fashionable"}', NULL, 3, 1308, NULL),
(1309, 'fast', '/fæst/', 'adjective', '{"zh-TW":["【主要意義-形容詞/副詞】快速的；快速地","【次要意義-名詞】齋戒；禁食期間","【次要意義-動詞】齋戒；禁食","【次要意義-形容詞】牢固的；緊緊的"],"en":["[primary] moving quickly; at high speed","[secondary - noun] a period of not eating for religious or health reasons","[secondary - verb] to abstain from food","[secondary - adjective] firmly fixed; secure"]}', NULL, 'break a fast / fast for a day / hold fast / fast asleep', '[{"en":"Employees observed a religious fast during the holiday period.","zh-TW":"員工在假期期間遵守宗教齋戒。"},{"en":"He decided to fast for 24 hours as part of the charity event.","zh-TW":"他決定禁食24小時以參與慈善活動。"},{"en":"The boat was held fast to the dock by two thick ropes.","zh-TW":"船被兩條粗繩牢牢地固定在碼頭上。"}]', '{"noun":"fasting","adjective":"fasting"}', 'fast 作名詞/動詞表「齋戒/禁食」，作形容詞表「固定的/牢固的」（如 fast asleep），這些用法在 TOEIC 文化或健康主題文章中偶爾出現。', 1, 1309, NULL),
(1310, 'fatal', '/ˈfeɪtəl/', 'adjective', '{"zh-TW":["致命的；嚴重的"],"en":["causing death; leading to failure"]}', NULL, 'fatal error/accident', '[{"en":"The software had a fatal error.","zh-TW":"軟體出現了致命錯誤。"},{"en":"The accident proved to be fatal.","zh-TW":"事故被證明是致命的。"}]', '{"noun":"fatality","adjective":"fatal","adverb":"fatally"}', NULL, 2, 1310, NULL),
(1311, 'father', '/ˈfɑːðər/', 'noun', '{"zh-TW":["父親"],"en":["a male parent"]}', NULL, 'founding father / father figure', '[{"en":"He is considered the founding father of the company.","zh-TW":"他被視為公司的創始人。"},{"en":"My father works in banking.","zh-TW":"我的父親在銀行業工作。"}]', '{"noun":"father","adjective":"fatherly","noun2":"fatherhood"}', NULL, 2, 1311, NULL),
(1312, 'fault', '/fɔːlt/', 'noun', '{"zh-TW":["過失；缺陷"],"en":["responsibility for a mistake; a defect"]}', NULL, 'at fault / find fault with', '[{"en":"The delay was not our fault.","zh-TW":"延誤不是我們的過失。"},{"en":"A fault was found in the equipment.","zh-TW":"在設備中發現了缺陷。"}]', '{"noun":"fault","adjective":"faulty"}', NULL, 2, 1312, NULL),
(1313, 'favor', '/ˈfeɪvər/', 'noun / verb', '{"zh-TW":["偏好；支持"],"en":["approval or support; to prefer"]}', NULL, 'in favor of', '[{"en":"The board voted in favor of the merger.","zh-TW":"董事會投票支持合併。"},{"en":"Most customers favor online shopping.","zh-TW":"大多數客戶偏好網上購物。"}]', '{"noun":"favor","verb":"favor","adjective":"favorable/favorite"}', NULL, 2, 1313, NULL),
(1314, 'fax', '/fæks/', 'noun', '{"zh-TW":["傳真"],"en":["a system for transmitting documents electronically over phone lines"]}', NULL, 'send a fax / fax machine', '[{"en":"Please fax the signed contract to our office.","zh-TW":"請將已簽署的合約傳真至我們的辦公室。"},{"en":"The fax number is listed on our website.","zh-TW":"傳真號碼列在我們的網站上。"}]', '{"verb":"fax","adjective":"faxed"}', NULL, 1, 1314, NULL),
(1315, 'fear', '/fɪr/', 'noun', '{"zh-TW":["恐懼；擔心"],"en":["an unpleasant emotion caused by danger"]}', NULL, 'for fear of / overcome fear', '[{"en":"She quit for fear of being laid off.","zh-TW":"她因害怕被裁員而辭職。"},{"en":"Overcome your fear of public speaking.","zh-TW":"克服你對公開演講的恐懼。"}]', '{"noun":"fear","verb":"fear","adjective":"fearful","adjective2":"fearless"}', NULL, 1, 1315, NULL),
(1316, 'feasibility', '/ˌfiːzəˈbɪlɪti/', 'noun', '{"zh-TW":["可行性"],"en":["the likelihood of a plan succeeding"]}', NULL, 'feasibility study / assess feasibility', '[{"en":"A feasibility study was conducted before launching the project.","zh-TW":"在啟動項目之前進行了可行性研究。"},{"en":"The report assessed the feasibility of building a new factory.","zh-TW":"報告評估了建設新工廠的可行性。"}]', '{"adjective":"feasible","adverb":"feasibly"}', NULL, 4, 1316, 786),
(1317, 'feasible', '/ˈfiːzəbəl/', 'adjective', '{"zh-TW":["可行的"],"en":["possible and practical to do"]}', NULL, 'financially/technically feasible', '[{"en":"Is the plan financially feasible?","zh-TW":"這個計畫在財務上可行嗎？"},{"en":"We need to determine if the project is feasible.","zh-TW":"我們需要確定項目是否可行。"}]', '{"noun":"feasibility","adjective":"feasible"}', NULL, 3, 1317, 966),
(1318, 'feature', '/ˈfiːtʃər/', 'noun / verb', '{"zh-TW":["【主要意義-名詞】特徵；特色；功能","【次要意義-動詞】以……為主角；重點介紹；包含（作為特色）","【次要意義-名詞】（報紙/雜誌）特寫文章；專題報導"],"en":["[primary - noun] a distinctive quality or aspect of something","[secondary - verb] to include someone or something as an important part","[secondary - noun] a long article or program about a specific topic"]}', NULL, 'feature article / feature film / feature prominently / as a key feature', '[{"en":"The new product features an advanced noise-canceling system.","zh-TW":"新產品以先進的降噪系統為特色。"},{"en":"The brochure features our best-selling products from the past year.","zh-TW":"宣傳冊重點介紹了我們過去一年的暢銷產品。"},{"en":"A feature on sustainable packaging will appear in the next issue.","zh-TW":"關於可持續包裝的特寫文章將出現在下一期。"}]', '{"adjective":"featured"}', '動詞 feature = 「以……為特色/重點介紹」，名詞 feature = 「特寫報導/專題文章」，均是 TOEIC 廣告和媒體文章的常見用法，考生容易只記住名詞「特徵/功能」的意思。', 3, 1318, 361),
(1319, 'federal', '/ˈfedərəl/', 'adjective', '{"zh-TW":["聯邦的"],"en":["relating to a central government","relating to the national government"]}', NULL, 'federal government/law; federal government / federal law', '[{"en":"The federal government announced new regulations.","zh-TW":"聯邦政府宣布了新法規。"},{"en":"Federal taxes apply to all states.","zh-TW":"聯邦稅適用於所有州。"},{"en":"It''s a federal offense.","zh-TW":"這是聯邦罪行。"},{"en":"The federal government announced new policies.","zh-TW":"聯邦政府宣布了新政策。"}]', '{"noun":"federation","adjective":"federal"}', NULL, 3, 1319, NULL),
(1320, 'fee', '/fiː/', 'noun', '{"zh-TW":["費用；手續費"],"en":["a payment made for professional services"]}', NULL, 'annual/membership fee', '[{"en":"There is a monthly membership fee of $50.","zh-TW":"每月會費為50美元。"},{"en":"Legal fees can be expensive.","zh-TW":"法律費用可能很昂貴。"}]', '{"noun":"fee"}', NULL, 1, 1320, NULL),
(1321, 'feedback', '/ˈfiːdbæk/', 'noun', '{"zh-TW":["反饋；回饋"],"en":["information about reactions to a product or performance"]}', NULL, 'provide/give feedback', '[{"en":"We appreciate your feedback on our service.","zh-TW":"我們感謝您對我們服務的反饋。"},{"en":"The manager gave constructive feedback.","zh-TW":"經理給予了建設性的反饋。"}]', '{"noun":"feedback"}', NULL, 3, 1321, 362),
(1322, 'feel', '/fiːl/', 'verb', '{"zh-TW":["感覺；覺得"],"en":["to experience an emotion","to be aware of through touch"]}', NULL, 'feel free / feel like', '[{"en":"Feel free to ask any questions.","zh-TW":"請隨時提問。"},{"en":"I feel confident about this decision.","zh-TW":"我對這個決定感到有信心。"}]', '{"verb":"feel","noun":"feeling"}', NULL, 1, 1322, NULL),
(1323, 'feeling', 'ˈfiːlɪŋ', 'noun', '{"zh-TW":["感覺；情感","感受"],"en":["an emotion or sentiment","a physical sensation"]}', NULL, 'gut feeling/mixed feelings', '[{"en":"I have a good feeling about this deal.","zh-TW":"我對這筆交易有好的感覺。"}]', '{"verb":"feel","adjective":"feeling"}', NULL, 3, 1323, NULL),
(1324, 'fellowship', '/ˈfɛloʊʃɪp/', 'noun', '{"zh-TW":["獎學金；研究員資格"],"en":["money given for academic study; companionship"]}', NULL, 'research fellowship / fellowship program', '[{"en":"He received a research fellowship.","zh-TW":"他獲得了研究獎學金。"},{"en":"The fellowship covers tuition and living expenses.","zh-TW":"該獎學金包含學費和生活費。"}]', NULL, NULL, 4, 1324, NULL),
(1325, 'felony', '/ˈfɛləni/', 'noun', '{"zh-TW":["重罪"],"en":["a serious crime"]}', NULL, 'commit a felony / felony charge', '[{"en":"Murder is classified as a felony.","zh-TW":"謀殺被歸類為重罪。"},{"en":"He was charged with a felony.","zh-TW":"他被指控犯了重罪。"}]', NULL, NULL, 2, 1325, NULL),
(1326, 'few', '/fjuː/', 'adjective', '{"zh-TW":["少數的；幾個"],"en":["a small number of"]}', NULL, 'a few / quite a few', '[{"en":"A few candidates were shortlisted.","zh-TW":"幾位候選人進入了決選名單。"},{"en":"Quite a few people attended.","zh-TW":"相當多人出席了。"}]', '{"adjective":"few","adjective2":"fewer","adjective3":"fewest"}', NULL, 1, 1326, NULL),
(1327, 'fiduciary', '/fɪˈdjuːʃəri/', 'adjective', '{"zh-TW":["信託的；受託的"],"en":["involving the legal duty to act in another''s best interest"]}', NULL, 'fiduciary duty / fiduciary responsibility', '[{"en":"Trustees have a fiduciary duty to act in beneficiaries'' interests.","zh-TW":"受託人有法律義務以受益人的利益行事。"},{"en":"A fiduciary relationship requires the highest standard of care.","zh-TW":"信託關係要求最高標準的謹慎義務。"}]', '{"noun":"fiduciary"}', NULL, 3, 1327, NULL),
(1328, 'field', '/fiːld/', 'noun', '{"zh-TW":["【主要意義-名詞】田野；領域；專業範疇","【次要意義-動詞】處理；回應（問題/投訴）","【次要意義-動詞】派遣（球員/團隊）上場"],"en":["[primary - noun] an open area of land; an area of study or work","[secondary - verb] to deal with a question, complaint, or inquiry","[secondary - verb] to send out a team or person to deal with something"]}', NULL, 'field questions / field complaints / field a team / field of expertise', '[{"en":"The customer service team fielded over 200 calls on the first day of the sale.","zh-TW":"客服團隊在促銷活動第一天接聽了逾200通電話。"},{"en":"The spokesperson fielded difficult questions from reporters after the conference.","zh-TW":"發言人在記者招待會後處理了記者提出的棘手問題。"},{"en":"She is an expert in her field and consulted by major corporations.","zh-TW":"她是她所在領域的專家，被各大企業諮詢。"}]', '{"noun":"fieldwork"}', '動詞 field questions/calls/complaints = 「接聽/處理（詢問/投訴）」，是 TOEIC 客服和公關文章的常見用法，考生容易只認識名詞「田野/領域」的意思。', 2, 1328, NULL),
(1329, 'fight', '/faɪt/', 'verb', '{"zh-TW":["戰鬥；奮鬥"],"en":["to struggle against","to try hard to achieve"]}', NULL, 'fight for / fight against', '[{"en":"We must fight for our market share.","zh-TW":"我們必須為市場份額而戰。"},{"en":"They fought against the unfair regulation.","zh-TW":"他們反對不公平的法規。"}]', '{"verb":"fight","noun":"fight","noun2":"fighter"}', NULL, 2, 1329, NULL),
(1330, 'figure', '/ˈfɪɡjər/', 'noun / verb', '{"zh-TW":["數字；認為"],"en":["a number or amount; to think or calculate"]}', NULL, 'sales/profit figures', '[{"en":"Sales figures exceeded projections.","zh-TW":"銷售數字超出了預測。"},{"en":"We need to figure out the best approach.","zh-TW":"我們需要想出最佳方法。"}]', '{"noun":"figure","verb":"figure"}', NULL, 2, 1330, NULL),
(1331, 'file', '/faɪl/', 'noun / verb', '{"zh-TW":["檔案；提交"],"en":["a collection of data; to submit officially"]}', NULL, 'file a report/complaint', '[{"en":"Please file the documents in order.","zh-TW":"請按順序歸檔文件。"},{"en":"She filed a complaint with HR.","zh-TW":"她向人資部門提出了投訴。"}]', '{"noun":"file","verb":"file"}', NULL, 1, 1331, NULL),
(1332, 'filing', '/ˈfaɪlɪŋ/', 'noun', '{"zh-TW":["歸檔；存檔"],"en":["the organizing and storing of documents"]}', NULL, 'document filing / filing system', '[{"en":"Maintain an organized filing system for all records.","zh-TW":"為所有記錄維護有組織的歸檔系統。"},{"en":"The filing of tax documents must be completed by March.","zh-TW":"稅務文件的歸檔必須在三月前完成。"}]', '{"verb":"file","noun":"file","adjective":"filed"}', NULL, 2, 1332, NULL),
(1333, 'fill', '/fɪl/', 'verb', '{"zh-TW":["填寫；填充"],"en":["to make full; to complete a form"]}', NULL, 'fill in/out a form', '[{"en":"Please fill out this application form.","zh-TW":"請填寫此申請表。"},{"en":"The position has been filled.","zh-TW":"該職位已被填補。"}]', '{"noun":"filling","verb":"fill"}', NULL, 1, 1333, NULL),
(1334, 'film', '/fɪlm/', 'noun', '{"zh-TW":["電影；影片"],"en":["a movie","a thin layer"]}', NULL, 'film industry / short film', '[{"en":"The film industry employs thousands.","zh-TW":"電影產業雇用了數千人。"},{"en":"We made a short promotional film.","zh-TW":"我們製作了一部短宣傳影片。"}]', '{"noun":"film","verb":"film","noun2":"filmmaker","noun3":"filming"}', NULL, 1, 1334, NULL),
(1335, 'final', '/ˈfaɪnəl/', 'adjective', '{"zh-TW":["最終的；最後的"],"en":["last; conclusive"]}', NULL, 'final decision/version', '[{"en":"The final decision rests with the board.","zh-TW":"最終決定權在董事會。"},{"en":"Submit the final version by Friday.","zh-TW":"請在週五前提交最終版本。"}]', '{"noun":"final/finale/finalist","verb":"finalize","adjective":"final","adverb":"finally"}', NULL, 2, 1335, 363),
(1336, 'finalize', '/ˈfaɪnəlaɪz/', 'verb', '{"zh-TW":["確定；敲定"],"en":["to complete the last details of a plan or document"]}', NULL, 'finalize the contract / finalize the agenda', '[{"en":"Please finalize the report before the board meeting.","zh-TW":"請在董事會議前確定報告。"},{"en":"We need to finalize the terms before signing.","zh-TW":"我們需要在簽署前敲定條款。"}]', '{"noun":"finalization","adjective":"finalized"}', NULL, 3, 1336, NULL),
(1337, 'finance', '/ˈfaɪnæns/', 'noun / verb', '{"zh-TW":["財務；資助"],"en":["the management of money; to provide funds"]}', NULL, 'personal/corporate finance', '[{"en":"She works in the finance department.","zh-TW":"她在財務部門工作。"},{"en":"The project is financed by private investors.","zh-TW":"該項目由私人投資者資助。"}]', '{"noun":"finance/financing","verb":"finance","adjective":"financial","adverb":"financially"}', NULL, 3, 1337, NULL),
(1338, 'find', 'faɪnd', 'verb', '{"zh-TW":["找到；發現","認為"],"en":["to locate something","to discover"]}', NULL, 'find a solution/error', '[{"en":"Please find the missing invoice.","zh-TW":"請找到遺失的發票。"}]', '{"noun":"finding","adjective":"findable"}', NULL, 1, 1338, NULL),
(1339, 'finding', '/ˈfaɪndɪŋ/', 'noun', '{"zh-TW":["發現；調查結果"],"en":["information discovered as a result of research"]}', NULL, 'key/research findings', '[{"en":"The findings were published in the report.","zh-TW":"調查結果已發表在報告中。"},{"en":"Key findings indicate a shift in trends.","zh-TW":"主要發現顯示趨勢轉變。"}]', '{"noun":"finding","verb":"find"}', NULL, 3, 1339, NULL),
(1340, 'fine', '/faɪn/', 'noun / verb / adjective', '{"zh-TW":["【主要意義-形容詞】好的；晴朗的；精緻的","【次要意義-名詞】罰款","【次要意義-動詞】對……處以罰款","【次要意義-副詞】很好地；細緻地"],"en":["[primary - adjective] of high quality; well; clear weather","[secondary - noun] a sum of money paid as a penalty","[secondary - verb] to require someone to pay a fine"]}', NULL, 'pay a fine / impose a fine / fine someone for / traffic fine', '[{"en":"The company was fined $50,000 for violating environmental regulations.","zh-TW":"該公司因違反環保法規被罰款5萬美元。"},{"en":"He received a fine for parking in a restricted zone.","zh-TW":"他因在禁止停車區停車而收到罰款單。"},{"en":"The regulator has the authority to fine companies for non-compliance.","zh-TW":"監管機構有權對不合規的公司進行罰款。"}]', '{"noun":"fining"}', 'fine 作名詞/動詞意為「罰款」，是 TOEIC 法規、合規或政府公告類文章的常見詞，考生容易只記住「好的/晴朗的」這個意思。', 1, 1340, NULL),
(1341, 'finger', '/ˈfɪŋɡər/', 'noun', '{"zh-TW":["手指"],"en":["one of the five parts at the end of the hand"]}', NULL, 'point the finger / finger on the pulse', '[{"en":"Don''t point the finger at others.","zh-TW":"別指責別人。"},{"en":"She has her finger on the pulse of the market.","zh-TW":"她對市場動態了然於胸。"}]', '{"noun":"finger","noun2":"fingertip","noun3":"fingerprint"}', NULL, 2, 1341, NULL),
(1342, 'finish', '/ˈfɪnɪʃ/', 'verb', '{"zh-TW":["完成；結束"],"en":["to complete","to come to an end"]}', NULL, 'finish on time / finish line', '[{"en":"We need to finish by the deadline.","zh-TW":"我們必須在截止日期前完成。"},{"en":"The project is nearly finished.","zh-TW":"專案快要完成了。"}]', '{"verb":"finish","noun":"finish"}', NULL, 2, 1342, NULL),
(1343, 'fintech', '/ˈfɪntek/', 'noun', '{"zh-TW":["金融科技"],"en":["technology-driven innovation in financial services"]}', NULL, 'use fintech / fintech startup / fintech sector', '[{"en":"Fintech companies are disrupting traditional banking models.","zh-TW":"金融科技公司正在顛覆傳統銀行模式。"},{"en":"The fintech platform allows users to transfer money instantly.","zh-TW":"金融科技平台允許用戶即時轉帳。"}]', NULL, NULL, 3, 1343, NULL),
(1344, 'fire', '/ˈfaɪər/', 'noun', '{"zh-TW":["火；火災；解雇"],"en":["combustion","to dismiss from a job"]}', NULL, 'catch fire / fire drill', '[{"en":"We conduct fire drills every quarter.","zh-TW":"我們每季進行消防演練。"},{"en":"He was fired for misconduct.","zh-TW":"他因行為不當被解雇。"}]', '{"noun":"fire","verb":"fire","noun2":"firefighter"}', NULL, 1, 1344, NULL),
(1345, 'firewall', '/ˈfaɪərwɔːl/', 'noun', '{"zh-TW":["防火牆"],"en":["a system that prevents unauthorized access"]}', NULL, 'set up a firewall / firewall protection', '[{"en":"The firewall blocked the attack.","zh-TW":"防火牆阻擋了攻擊。"},{"en":"Make sure your firewall is active.","zh-TW":"確認你的防火牆已啟用。"}]', NULL, NULL, 3, 1345, NULL),
(1346, 'firm', '/fɜːrm/', 'noun / adjective', '{"zh-TW":["公司；堅定的"],"en":["a business; strong and unlikely to change"]}', NULL, 'law/consulting firm', '[{"en":"She works for a consulting firm.","zh-TW":"她在一家顧問公司工作。"},{"en":"The manager was firm in her decision.","zh-TW":"經理對她的決定很堅定。"}]', '{"noun":"firm","adjective":"firm","adverb":"firmly"}', NULL, 1, 1346, NULL),
(1347, 'firmware', '/ˈfɜːrmwɛr/', 'noun', '{"zh-TW":["韌體"],"en":["software built into hardware devices"]}', NULL, 'firmware update / latest firmware', '[{"en":"Update the firmware to fix the issue.","zh-TW":"更新韌體以修復問題。"},{"en":"The firmware controls the hardware.","zh-TW":"韌體控制硬體。"}]', NULL, NULL, 3, 1347, NULL),
(1348, 'fiscal', '/ˈfɪskəl/', 'adjective', '{"zh-TW":["財政的"],"en":["relating to government revenue and spending"]}', NULL, 'fiscal year/policy', '[{"en":"The fiscal year ends in March.","zh-TW":"會計年度在三月結束。"},{"en":"Fiscal policy affects economic growth.","zh-TW":"財政政策影響經濟增長。"}]', '{"adjective":"fiscal"}', NULL, 2, 1348, NULL),
(1349, 'fish', '/fɪʃ/', 'noun', '{"zh-TW":["魚"],"en":["a cold-blooded animal living in water"]}', NULL, 'a big fish / fish for compliments', '[{"en":"He is a big fish in the industry.","zh-TW":"他是業界的大人物。"},{"en":"Fresh fish is served daily.","zh-TW":"每天供應新鮮魚類。"}]', '{"noun":"fish","verb":"fish","noun2":"fishing","noun3":"fisherman"}', NULL, 1, 1349, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(1350, 'fit', '/fɪt/', 'verb / adjective', '{"zh-TW":["適合；健康的"],"en":["to be the right size; suitable"]}', NULL, 'fit for purpose / a good fit', '[{"en":"This candidate is a good fit for the role.","zh-TW":"這位候選人很適合這個職位。"},{"en":"The product must be fit for purpose.","zh-TW":"產品必須適合其用途。"}]', '{"noun":"fitness","verb":"fit","adjective":"fit/fitting"}', NULL, 1, 1350, NULL),
(1351, 'fitness', '/ˈfɪtnəs/', 'noun', '{"zh-TW":["健身；適合度"],"en":["the condition of being physically healthy"]}', NULL, 'fitness center / physical fitness', '[{"en":"She goes to the fitness center daily.","zh-TW":"她每天去健身中心。"},{"en":"Regular exercise improves fitness.","zh-TW":"規律運動能改善體能。"}]', '{"adjective":"fit"}', NULL, 3, 1351, NULL),
(1352, 'fix', '/fɪks/', 'verb', '{"zh-TW":["修理；固定"],"en":["to repair; to fasten securely"]}', NULL, 'fix a problem/bug', '[{"en":"The technician fixed the printer.","zh-TW":"技術人員修好了印表機。"},{"en":"We need to fix this issue urgently.","zh-TW":"我們需要緊急修復這個問題。"}]', '{"noun":"fix","verb":"fix","adjective":"fixed"}', NULL, 1, 1352, NULL),
(1353, 'flag', '/flæɡ/', 'verb, noun', '{"zh-TW":["【主要意義-名詞】旗子；旗幟","【次要意義-動詞】衰弱；精力下降；熱情減退","【次要意義-動詞】標記；標示（需注意之處）"],"en":["[primary - noun] a piece of cloth used as a symbol or signal","[secondary - verb] to become tired or less enthusiastic","[secondary - verb] to mark something for attention"]}', NULL, 'flag down / energy flags / flag a concern', '[{"en":"His enthusiasm for the project began to flag after months of setbacks.","zh-TW":"經過幾個月的挫折後，他對這個專案的熱情開始消退。"},{"en":"The editor flagged several errors in the report.","zh-TW":"編輯在報告中標記了幾個錯誤。"},{"en":"Sales flagged in the third quarter due to market uncertainty.","zh-TW":"由於市場不確定性，第三季度的銷售額下滑。"}]', '{"noun":"flagging","adjective":"flagging"}', '動詞 flag 表示「精力/興趣衰退」或「標記」，與旗子完全無關，常見於 TOEIC 閱讀描述業務下滑或編輯流程的文章中。', 1, 1353, NULL),
(1354, 'flat', '/flæt/', 'adjective, adverb, noun', '{"zh-TW":["【主要意義-形容詞】平的；扁平的","【次要意義-副詞】斷然地；完全地；一口回絕地","【次要意義-形容詞】平淡的；無聊的；沒電的（電池）","【次要意義-名詞（英式）】公寓"],"en":["[primary - adjective] having a level surface","[secondary - adverb] in a direct and definite way; absolutely","[secondary - adjective] dull and lacking energy; (of a battery) having no charge","[secondary - noun (British English)] an apartment"]}', NULL, 'fall flat / flat out / flat rate / turn someone down flat / flat denial', '[{"en":"She turned down the offer flat, without any further discussion.","zh-TW":"她斷然拒絕了這個提議，沒有作進一步的討論。"},{"en":"The new product launch fell flat despite heavy promotion.","zh-TW":"儘管大力宣傳，新產品的發布還是沒有引起反響。"},{"en":"The company charges a flat rate of 200 dollars per month for the service.","zh-TW":"公司對該服務收取每月200美元的固定費率。"}]', '{"adverb":"flatly","noun":"flatness"}', 'flat 作副詞表「斷然地」（turn down flat = 斷然拒絕），fall flat（失敗/沒有效果），flat rate（固定費率）均是 TOEIC 商業文章的高頻表達，flat（英式）= 公寓也常出現。', 1, 1354, NULL),
(1355, 'flexibility', 'ˌflɛksɪˈbɪlɪti', 'noun', '{"zh-TW":["靈活性；彈性","適應性"],"en":["the ability to adapt","being easily changed"]}', NULL, 'flexibility in scheduling/workplace flexibility', '[{"en":"We value flexibility in working arrangements.","zh-TW":"我們重視工作安排的靈活性。"}]', '{"adjective":"flexible","adverb":"flexibly"}', NULL, 4, 1355, NULL),
(1356, 'flexible', '/ˈfleksəbəl/', 'adjective', '{"zh-TW":["靈活的；彈性的","靈活的；有彈性的"],"en":["able to change or be changed easily","capable of bending easily","willing to change or compromise"]}', '{"root":{"text":"flex","meaning":"bend (彎曲)"},"suffix":{"text":"-ible","meaning":"able to (能夠)"},"logic":"能夠彎曲的，即「靈活的」。"}', 'flexible schedule/hours; flexible schedule / flexible approach', '[{"en":"We offer flexible working hours.","zh-TW":"我們提供彈性工作時間。"},{"en":"The policy needs to be more flexible.","zh-TW":"政策需要更加靈活。"},{"en":"We need a more flexible approach.","zh-TW":"我們需要更靈活的做法。"},{"en":"The company offers flexible working hours.","zh-TW":"公司提供彈性工作時間。"}]', '{"noun":"flexibility","adjective":"flexible","adverb":"flexibly"}', NULL, 3, 1356, 364),
(1357, 'flight', '/flaɪt/', 'noun', '{"zh-TW":["飛行；航班"],"en":["a journey made by flying"]}', NULL, 'scheduled flight / charter flight', '[{"en":"Our flight departs at seven in the morning.","zh-TW":"我們的航班早上七點出發。"},{"en":"The flight was smooth with no turbulence.","zh-TW":"航班飛行平穩，沒有亂流。"}]', '{"verb":"fly","adjective":"airborne"}', NULL, 2, 1357, NULL),
(1358, 'float', '/floʊt/', 'verb', '{"zh-TW":["浮動；漂浮"],"en":["to rest on the surface; to allow exchange rate to vary"]}', NULL, 'float on the market', '[{"en":"The company floated on the stock exchange.","zh-TW":"公司在股票交易所上市。"},{"en":"The currency was allowed to float freely.","zh-TW":"貨幣被允許自由浮動。"}]', '{"noun":"flotation","verb":"float","adjective":"floating"}', NULL, 2, 1358, NULL),
(1359, 'flood', '/flʌd/', 'noun', '{"zh-TW":["洪水"],"en":["an overflow of water onto normally dry land"]}', '{"root":{"text":"flood","meaning":"flow (流動)"},"logic":"源自古英語 flōd（大水流動）。"}', 'flash flood / flood damage / flood warning', '[{"en":"The flood destroyed hundreds of homes.","zh-TW":"洪水摧毀了數百戶房屋。"},{"en":"Heavy rains caused severe flooding in the area.","zh-TW":"大雨在該地區造成嚴重水災。"}]', '{"verb":"flood","noun":"flooding"}', NULL, 2, 1359, NULL),
(1360, 'floor', '/flɔːr/', 'noun', '{"zh-TW":["地板；樓層"],"en":["the lower surface of a room","a level of a building"]}', NULL, 'ground floor / sales floor', '[{"en":"The office is on the third floor.","zh-TW":"辦公室在三樓。"},{"en":"The sales floor is very spacious.","zh-TW":"銷售樓層很寬敞。"}]', '{"noun":"floor","noun2":"flooring"}', NULL, 2, 1360, NULL),
(1361, 'flourish', '/ˈflɜːrɪʃ/', 'verb', '{"zh-TW":["繁榮；蓬勃發展"],"en":["to grow or develop successfully"]}', NULL, 'business flourishes', '[{"en":"The business flourished under new management.","zh-TW":"在新管理層下企業蓬勃發展。"},{"en":"Creativity flourishes in a supportive environment.","zh-TW":"創造力在支持性環境中蓬勃發展。"}]', '{"verb":"flourish","adjective":"flourishing"}', NULL, 3, 1361, NULL),
(1362, 'flow', '/floʊ/', 'noun / verb', '{"zh-TW":["流動；流程"],"en":["the movement of something; to move steadily"]}', NULL, 'cash flow / workflow', '[{"en":"The company has positive cash flow.","zh-TW":"公司有正向的現金流。"},{"en":"Information flows between departments.","zh-TW":"資訊在部門間流動。"}]', '{"noun":"flow","verb":"flow"}', NULL, 1, 1362, NULL),
(1363, 'flower', '/ˈflaʊər/', 'noun', '{"zh-TW":["花"],"en":["the colorful part of a plant"]}', NULL, 'flower arrangement / flower shop', '[{"en":"We ordered flower arrangements for the event.","zh-TW":"我們為活動訂了花藝。"},{"en":"The flower shop is on the corner.","zh-TW":"花店在轉角。"}]', '{"noun":"flower","adjective":"flowery","verb":"flower"}', NULL, 2, 1363, NULL),
(1364, 'fluctuate', '/ˈflʌktʃueɪt/', 'verb', '{"zh-TW":["波動；變動"],"en":["to rise and fall irregularly"]}', NULL, 'fluctuate between/widely', '[{"en":"Prices fluctuate depending on demand.","zh-TW":"價格隨需求波動。"},{"en":"The stock price fluctuated throughout the day.","zh-TW":"股價全天波動。"}]', '{"noun":"fluctuation","verb":"fluctuate"}', NULL, 3, 1364, 874),
(1365, 'fluctuation', '/ˌflʌktʃuˈeɪʃən/', 'noun', '{"zh-TW":["波動；起伏"],"en":["irregular changes in level, amount, or value"]}', NULL, 'price fluctuation / exchange rate fluctuation', '[{"en":"Currency fluctuations affected the cost of imported goods.","zh-TW":"貨幣波動影響了進口商品的成本。"},{"en":"The market experienced significant fluctuations last year.","zh-TW":"市場去年經歷了顯著的波動。"}]', '{"verb":"fluctuate","adjective":"fluctuating"}', NULL, 4, 1365, 787),
(1366, 'fly', '/flaɪ/', 'verb', '{"zh-TW":["飛；搭飛機"],"en":["to move through the air","to travel by airplane"]}', NULL, 'fly abroad / fly business class', '[{"en":"I fly to Tokyo every month for work.","zh-TW":"我每個月飛東京出差。"},{"en":"Time flies when you are busy.","zh-TW":"忙碌時時間過得很快。"}]', '{"verb":"fly","noun":"flight","noun2":"flyer"}', NULL, 1, 1366, NULL),
(1367, 'focus', '/ˈfoʊkəs/', 'noun / verb', '{"zh-TW":["焦點；專注"],"en":["the center of attention; to concentrate"]}', NULL, 'focus on / main focus', '[{"en":"Our main focus is customer satisfaction.","zh-TW":"我們的主要焦點是客戶滿意度。"},{"en":"We need to focus on core business.","zh-TW":"我們需要專注於核心業務。"}]', '{"noun":"focus","verb":"focus","adjective":"focused"}', NULL, 2, 1367, NULL),
(1368, 'focused', 'ˈfoʊkəst', 'adjective', '{"zh-TW":["專注的；集中的","重點的"],"en":["directing attention to one thing","concentrated"]}', NULL, 'results-focused/customer-focused', '[{"en":"Stay focused on the main objective.","zh-TW":"保持對主要目標的專注。"}]', '{"verb":"focus","noun":"focus","adverb":"with focus"}', NULL, 3, 1368, NULL),
(1369, 'fog', '/fɒɡ/', 'noun', '{"zh-TW":["霧"],"en":["thick cloud of tiny water droplets near the ground"]}', '{"root":{"text":"fog","meaning":"mist (霧)"},"logic":"指地面附近的濃密水滴雲。"}', 'dense fog / fog advisory / foggy morning', '[{"en":"The fog reduced visibility to less than 50 meters.","zh-TW":"霧使能見度降到不足50公尺。"},{"en":"Drive carefully in the fog.","zh-TW":"在霧中小心開車。"}]', '{"adjective":"foggy"}', NULL, 1, 1369, NULL),
(1370, 'folio', '/ˈfəʊliəʊ/', 'noun', '{"zh-TW":["帳單；帳戶明細"],"en":["an itemized bill at a hotel"]}', NULL, 'review your folio / settle the folio', '[{"en":"Please review your folio before checking out.","zh-TW":"退房前請查看您的帳單。"},{"en":"Any incidental charges will appear on your folio.","zh-TW":"任何雜費將顯示在您的帳單上。"}]', NULL, NULL, 2, 1370, NULL),
(1371, 'follow', '/ˈfɑːloʊ/', 'verb', '{"zh-TW":["【主要意義-動詞】跟隨；跟著","【次要意義-動詞】理解；明白（口語）","【次要意義-動詞】從事（職業）；遵循（流程）","【次要意義-動詞】密切關注；追蹤（新聞/情況）"],"en":["[primary] to go behind or after someone","[secondary] to understand or keep track of an explanation","[secondary] to pursue an occupation or practice","[secondary] to pay close attention to events or developments"]}', NULL, 'follow up / follow through / follow suit / as follows / follow the procedure', '[{"en":"Please follow up with the client within 24 hours of the initial inquiry.","zh-TW":"請在初次詢問後24小時內跟進客戶。"},{"en":"I am not sure I follow your point; could you clarify?","zh-TW":"我不確定我是否理解您的觀點，您能澄清一下嗎？"},{"en":"The terms of payment are as follows: 30 percent upfront, 70 percent on delivery.","zh-TW":"付款條款如下：預付30%，交貨時支付70%。"}]', '{"noun":"follow-up, following","adjective":"following"}', 'follow up（跟進）、as follows（如下）、follow through（貫徹執行）均是 TOEIC 商業郵件和合約的必考表達，動詞 follow = 「理解」也是常見口語陷阱。', 2, 1371, NULL),
(1372, 'follow-up', '/ˈfɒloʊ ʌp/', 'noun', '{"zh-TW":["跟進；後續行動"],"en":["an action or communication taken after an initial contact or meeting"]}', NULL, 'send a follow-up / follow-up email / follow-up call / follow-up meeting', '[{"en":"She sent a follow-up email after the sales call.","zh-TW":"電話銷售後她發了一封跟進郵件。"},{"en":"All action items require a follow-up at the next meeting.","zh-TW":"所有行動事項都需要在下次會議上跟進。"}]', '{"verb":"follow up","adjective":"follow-up"}', NULL, 3, 1372, NULL),
(1373, 'food', '/fuːd/', 'noun', '{"zh-TW":["食物"],"en":["substances eaten for nutrition"]}', NULL, 'food industry / fast food', '[{"en":"The food industry is highly regulated.","zh-TW":"食品產業受到嚴格監管。"},{"en":"We provide food for the conference.","zh-TW":"我們為會議提供餐點。"}]', '{"noun":"food","noun2":"foodie"}', NULL, 1, 1373, NULL),
(1374, 'foot', '/fʊt/', 'noun', '{"zh-TW":["【主要意義-名詞】腳；英尺（單位）","【次要意義-動詞】支付（帳單）；承擔費用","【次要意義-動詞】（數字）合計；加總"],"en":["[primary - noun] the body part at the bottom of the leg; a unit of length","[secondary - verb] to pay a bill or cost","[secondary - verb] to add up a column of numbers"]}', NULL, 'foot the bill / foot the cost / on foot / under foot', '[{"en":"The company agreed to foot the bill for all relocation expenses.","zh-TW":"公司同意承擔所有搬遷費用。"},{"en":"The client expected the contractor to foot the cost of any repairs.","zh-TW":"客戶期望承包商承擔所有修繕費用。"},{"en":"The sales team visited local branches on foot to meet clients personally.","zh-TW":"銷售團隊步行拜訪當地分支機構，親自會見客戶。"}]', '{"noun":"footage, footprint","verb":"footnote"}', 'foot the bill = 「承擔/支付費用」是 TOEIC 財務和商業協議文章的高頻表達，考生容易誤以為 foot 只有「腳」或「英尺」的意思。', 1, 1374, NULL),
(1375, 'footprint', '/ˈfʊtprɪnt/', 'noun', '{"zh-TW":["足跡；規模"],"en":["the extent of a company operations or presence in a market"]}', NULL, 'expand the footprint / reduce the environmental footprint', '[{"en":"The retailer expanded its footprint to 500 stores across the country.","zh-TW":"零售商將其規模擴展到全國500家門市。"},{"en":"The company worked to reduce its carbon footprint by 30%.","zh-TW":"公司致力於將其碳足跡減少30%。"}]', NULL, NULL, 3, 1375, NULL),
(1376, 'forbid', '/fərˈbɪd/', 'verb', '{"zh-TW":["禁止"],"en":["to order someone not to do something"]}', NULL, 'strictly forbidden', '[{"en":"Smoking is forbidden in this building.","zh-TW":"這棟建築內禁止吸菸。"},{"en":"Company policy forbids personal use of equipment.","zh-TW":"公司政策禁止私人使用設備。"}]', '{"verb":"forbid","adjective":"forbidden"}', NULL, 2, 1376, NULL),
(1377, 'force', '/fɔːrs/', 'noun / verb', '{"zh-TW":["力量；迫使"],"en":["strength or power; to make someone do something"]}', NULL, 'by force / in force', '[{"en":"The new regulations are now in force.","zh-TW":"新法規現已生效。"},{"en":"Budget cuts forced the company to downsize.","zh-TW":"預算削減迫使公司裁員。"}]', '{"noun":"force","verb":"force","adjective":"forceful"}', NULL, 2, 1377, NULL),
(1378, 'forecast', '/ˈfɔːrkæst/', 'noun / verb', '{"zh-TW":["預測；預報","預報；預測"],"en":["a prediction about future events","a prediction of future events, especially weather"]}', '{"prefix":{"text":"fore-","meaning":"before (預先)"},"root":{"text":"cast","meaning":"throw/plan (投/計劃)"},"logic":"預先計劃推測，即「預報」。"}', 'sales/weather forecast; weather forecast / sales forecast', '[{"en":"The sales forecast looks promising.","zh-TW":"銷售預測看起來很樂觀。"},{"en":"Analysts forecast steady growth next year.","zh-TW":"分析師預測明年穩定增長。"},{"en":"The forecast says it will rain tomorrow.","zh-TW":"天氣預報說明天會下雨。"},{"en":"The economic forecast looks positive.","zh-TW":"經濟預測看起來樂觀。"}]', '{"noun":"forecast","verb":"forecast"}', NULL, 3, 1378, 125),
(1379, 'foreclosure', '/fɔːrˈkloʊʒər/', 'noun', '{"zh-TW":["法拍；喪失抵押品贖回權"],"en":["the legal process by which a lender seizes property due to mortgage default"]}', NULL, 'face foreclosure / foreclosure process / prevent foreclosure', '[{"en":"The family faced foreclosure after missing six mortgage payments.","zh-TW":"這個家庭在錯過六次按揭還款後面臨法拍。"},{"en":"Foreclosure proceedings were halted after the owners found a buyer.","zh-TW":"業主找到買家後，法拍程序被中止。"}]', '{"verb":"foreclose"}', NULL, 4, 1379, NULL),
