(1391, 'forward', '/ˈfɔːrwərd/', 'verb', '{"zh-TW":["轉發；轉寄"],"en":["to send or pass on to another person"]}', NULL, 'forward an email / forward the proposal', '[{"en":"Please forward the attached report to your manager.","zh-TW":"請將附件報告轉發給您的經理。"},{"en":"I''ve forwarded your inquiry to the relevant department.","zh-TW":"我已將您的查詢轉發給相關部門。"}]', '{"adjective":"forward","adverb":"forward"}', NULL, 3, 1391, 126),
