(1393, 'forwarder', '/ˈfɔːrwərdər/', 'noun', '{"zh-TW":["貨運代理商；承攬運送業者"],"en":["a company that organizes shipments on behalf of importers or exporters"]}', NULL, 'freight forwarder / appoint a forwarder / forwarder services', '[{"en":"They hired a freight forwarder to handle the customs documentation.","zh-TW":"他們聘請了貨運代理商處理海關文件。"},{"en":"The forwarder coordinated the entire shipment from factory to port.","zh-TW":"貨運代理商協調了從工廠到港口的整個運輸過程。"}]', '{"full":"freight forwarder"}', NULL, 3, 1393, NULL),
