(1400, 'franchise', '/ˈfræntʃaɪz/', 'noun / verb', '{"zh-TW":["特許經營權；加盟"],"en":["a license to sell products under a brand name"]}', NULL, 'franchise agreement/owner', '[{"en":"He owns a fast-food franchise.","zh-TW":"他擁有一家速食加盟店。"},{"en":"The brand is looking to franchise internationally.","zh-TW":"該品牌正在尋求國際特許經營。"}]', '{"noun":"franchise/franchisee/franchisor","verb":"franchise"}', NULL, 3, 1400, NULL),
(1401, 'franchisee', '/ˌfræntʃaɪˈziː/', 'noun', '{"zh-TW":["加盟商；受許可人"],"en":["a person or company that has purchased the right to operate a franchised business"]}', NULL, 'recruit franchisees / support franchisees', '[{"en":"Each franchisee operates under the franchisor''s brand and standards.","zh-TW":"每個加盟商在特許經營者的品牌和標準下運營。"},{"en":"The franchisor provides training and marketing support to all franchisees.","zh-TW":"特許經營者為所有加盟商提供培訓和行銷支持。"}]', '{"opposite":"franchisor"}', NULL, 4, 1401, NULL),
