(1403, 'free', '/friː/', 'adjective / verb', '{"zh-TW":["免費的；自由的"],"en":["without cost; not restricted"]}', NULL, 'free of charge / free up', '[{"en":"The seminar is free of charge.","zh-TW":"研討會免費。"},{"en":"We need to free up some budget.","zh-TW":"我們需要騰出一些預算。"}]', '{"noun":"freedom","verb":"free","adjective":"free","adverb":"freely"}', NULL, 1, 1403, NULL),
(1404, 'free-range', '/friː reɪndʒ/', 'adjective', '{"zh-TW":["放養的；自由放牧的"],"en":["allowing animals to roam freely"]}', NULL, 'free-range chicken / free-range eggs', '[{"en":"The restaurant uses free-range chicken in all dishes.","zh-TW":"餐廳在所有菜餚中使用放養雞肉。"},{"en":"Free-range eggs have a richer flavor.","zh-TW":"放養雞蛋風味更豐富。"}]', NULL, NULL, 4, 1404, NULL),
