(1414, 'frustrated', '/frʌˈstreɪtɪd/', 'adjective', '{"zh-TW":["沮喪的；受挫的"],"en":["feeling upset because of inability to change or achieve something"]}', '{"root":{"text":"frustr","meaning":"in vain (徒勞)"},"suffix":{"text":"-ated","meaning":"state (狀態)"},"logic":"感到徒勞的狀態，即「受挫的」。"}', 'feel frustrated / frustrated with', '[{"en":"He felt frustrated with the slow progress.","zh-TW":"他對緩慢的進度感到挫折。"},{"en":"Customers are frustrated by the long wait times.","zh-TW":"顧客對漫長的等待時間感到不滿。"}]', '{"noun":"frustration","verb":"frustrate","adjective":"frustrating"}', NULL, 4, 1414, NULL),
