(1422, 'funnel', '/ˈfʌnəl/', 'noun', '{"zh-TW":["漏斗；行銷漏斗"],"en":["the stages a customer goes through from awareness to purchase"]}', NULL, 'sales funnel / marketing funnel / top of funnel / bottom of funnel', '[{"en":"Most website visitors drop off at the top of the funnel.","zh-TW":"大多數網站訪客在漏斗頂端就流失了。"},{"en":"The team optimized the funnel to reduce drop-off at checkout.","zh-TW":"團隊優化了漏斗以減少結帳時的流失。"}]', '{"verb":"funnel"}', NULL, 2, 1422, NULL),
