(1440, 'GDP', '/ˌdʒiː diː ˈpiː/', 'noun', '{"zh-TW":["國內生產總值"],"en":["gross domestic product; the total value of goods and services produced in a country"]}', NULL, 'GDP growth / GDP per capita / measure GDP', '[{"en":"The country''s GDP grew by 3% in the last fiscal year.","zh-TW":"該國上一財政年度的GDP增長了3%。"},{"en":"GDP is the most widely used measure of economic performance.","zh-TW":"GDP是最廣泛使用的經濟績效衡量標準。"}]', '{"full form":"gross domestic product"}', NULL, 1, 1440, NULL),
(1441, 'general', '/ˈdʒenərəl/', 'adjective', '{"zh-TW":["一般的；總體的"],"en":["affecting or including all; not specific"]}', NULL, 'in general / general manager', '[{"en":"In general, sales have been improving.","zh-TW":"一般來說，銷售一直在改善。"},{"en":"The general consensus is to proceed.","zh-TW":"普遍共識是繼續進行。"}]', '{"noun":"generalization","verb":"generalize","adjective":"general","adverb":"generally"}', NULL, 3, 1441, NULL),
(1442, 'generate', '/ˈdʒenəreɪt/', 'verb', '{"zh-TW":["產生；創造","產生；生成"],"en":["to produce or create"]}', '{"root":{"text":"gener","meaning":"birth/produce (生產)"},"suffix":{"text":"-ate","meaning":"make (使)"},"logic":"使其產生，即「生成」。"}', 'generate revenue/ideas; generate revenue / generate electricity / generate ideas', '[{"en":"The campaign generated significant revenue.","zh-TW":"該活動產生了可觀的收入。"},{"en":"Solar panels generate clean energy.","zh-TW":"太陽能板產生清潔能源。"},{"en":"The project will generate new jobs.","zh-TW":"這個專案將創造新的就業機會。"},{"en":"Solar panels generate electricity from sunlight.","zh-TW":"太陽能板從陽光產生電力。"}]', '{"noun":"generation/generator","verb":"generate","noun2":"generator"}', NULL, 3, 1442, 128),
(1443, 'generous', '/ˈdʒenərəs/', 'adjective', '{"zh-TW":["慷慨的；豐厚的","慷慨的；大方的"],"en":["willing to give more than expected","willing to give more than is expected"]}', '{"root":{"text":"gener","meaning":"birth/kind (出身/種類)"},"suffix":{"text":"-ous","meaning":"full of (充滿)"},"logic":"出身高貴而樂於給予的，即「慷慨的」。"}', 'generous offer/donation; generous donation / generous offer', '[{"en":"The company offers generous benefits.","zh-TW":"公司提供豐厚的福利。"},{"en":"It was a generous donation.","zh-TW":"這是一筆慷慨的捐贈。"},{"en":"She is very generous with her time.","zh-TW":"她很慷慨地付出時間。"},{"en":"That was a generous donation.","zh-TW":"那是一筆慷慨的捐款。"}]', '{"noun":"generosity","adjective":"generous","adverb":"generously"}', NULL, 3, 1443, NULL),
(1444, 'genuine', '/ˈdʒenjuɪn/', 'adjective', '{"zh-TW":["真正的；真誠的"],"en":["truly what it is said to be; sincere","truly what something is said to be; authentic"]}', '{"root":{"text":"genu","meaning":"birth/native (天生)"},"suffix":{"text":"-ine","meaning":"relating to (相關的)"},"logic":"與天生本性相關的，即「真正的」。"}', 'genuine concern/interest; genuine interest / genuine concern / genuine article', '[{"en":"She showed genuine interest in the project.","zh-TW":"她對該項目表現出真誠的興趣。"},{"en":"Is this a genuine product?","zh-TW":"這是正品嗎？"},{"en":"She showed genuine interest in the topic.","zh-TW":"她對這個話題表現出真正的興趣。"},{"en":"Is this a genuine Picasso painting?","zh-TW":"這是真的畢卡索畫作嗎？"}]', '{"adjective":"genuine","adverb":"genuinely"}', NULL, 3, 1444, NULL),
